const loopItem = $('Loop Over Items').first().json;
const personal = $('HTTP Request').first().json;
const q = $input.first().json?.response ?? {};

const services = [
  ...(q.requestedItems?.services ?? []),
  ...(q.recommendedItems?.services ?? []),
  ...(q.complementaryBudget?.services ?? []),
];

const pickup = services.find(s =>
  s.status === 'A' && /pick\s*up/i.test(`${s.categoryName ?? ''} ${s.serviceName ?? ''}`)
);

return [{
  json: {
    ...loopItem,
    response: personal.response,   // lo que lee Code3 (datos del cliente)
    cotizacion_ok: !!q.quotationId,
    pickup: !!pickup,
    pickup_servicio: pickup?.serviceName ?? '',
    pickup_precio: pickup?.price ?? 0,
    cotizacion_subtotal: q.subTotal ?? 0,
  }
}];

const inputData = $('Loop Over Items').first().json;
const cliente = $input.first().json;

return [{
  json: {
    columnas: {
      asesor:   String(inputData.asesor  ?? ""),
      cliente:  String(inputData.cliente ?? ""),
      fecha:    String(inputData.fecha   ?? ""),
      hora:     String(inputData.hora    ?? ""),
      patente:  String(inputData.patente ?? ""),
      vin:      String(inputData.vin     ?? ""),
      modelo:   String(inputData.modelo  ?? ""),
      telefono: String(cliente.telefono_normalizado ?? ""),
      telefono_original: String(cliente.telefono_original ?? ""),
      sucursal: "rosario"
    }
  }
}];

const res = $input.first().json.response ?? {};

// Arma el WhatsApp (549 + 10 dígitos) a partir de lo que está cargado en Ford.
// Corrige: área repetida dentro del número, "15" adelante o en el medio, número ya con 54/549.
// Si no se puede armar un número válido devuelve null y el turno NO se envía.
function normalizarTelefono(cityCode, phoneNumber) {
  const area = String(cityCode ?? '').replace(/\D/g, '').replace(/^0+/, '');
  let num = String(phoneNumber ?? '').replace(/\D/g, '').replace(/^0+/, '');
  if (!num) return null;
  // Ya viene con código de país
  if (num.startsWith('549') && num.length === 13) return num;
  if (num.startsWith('54') && num.length === 12) return '549' + num.slice(2);
  let nacional;
  if (num.length === 10 && num.startsWith('15') && area && area.length === 2) {
    nacional = area + num.slice(2);                   // 15 + número con área de 2 dígitos (ej. 011)
  } else if (num.length === 10) {
    nacional = num;                                   // número completo, ya trae el área
  } else if (area && num.length === 12 && num.startsWith(area) && num.slice(area.length, area.length + 2) === '15') {
    nacional = area + num.slice(area.length + 2);     // área + 15 + número
  } else {
    if (num.startsWith('15') && area && (area.length + num.length - 2) === 10) num = num.slice(2); // 15 adelante
    nacional = area + num;
  }
  if (nacional.length === 12 && area && nacional.slice(area.length, area.length + 2) === '15') {
    nacional = area + nacional.slice(area.length + 2);
  }
  if (nacional.length === 12) {                      // un 15 metido en el medio (ej. área 3411 + 53477115)
    const pos = [2, 3, 4].filter(p => nacional.slice(p, p + 2) === '15');
    if (pos.length === 1) nacional = nacional.slice(0, pos[0]) + nacional.slice(pos[0] + 2);
  }
  return /^[1-9]\d{9}$/.test(nacional) ? '549' + nacional : null;
}

const telefonoNormalizado = normalizarTelefono(res.mobilePhone?.cityCode, res.mobilePhone?.phoneNumber);

return [{
  json: {
    cliente_id:           res.id,
    nombre:               res.firstName,
    apellido:             res.lastName,
    nombre_completo:      `${res.firstName ?? ''} ${res.lastName ?? ''}`.trim(),
    dni:                  res.nationalId,
    email:                res.email,
    telefono_normalizado: telefonoNormalizado,
    telefono_original:    `${res.mobilePhone?.cityCode ?? ''} ${res.mobilePhone?.phoneNumber ?? ''}`.trim(),
  }
}];

// Junta los turnos de todas las páginas (cada página llega como un item) y saca duplicados por id
const vistos = new Set();
const allItems = $input.all().flatMap(inputItem => {
  const items = inputItem.json?.result?.items;
  if (!items) return [];
  return items;
}).filter(item => {
  if (!item?.id || vistos.has(item.id)) return false;
  vistos.add(item.id);
  return true;
}).map(item => ({
  json: {
    id:           item.id,
    fecha:        item.date?.slice(0, 10),
    hora:         item.date?.slice(11, 16),
    status:       item.status,
    source:       item.source,
    cliente:      `${item.conductorName?.firstName ?? ''} ${item.conductorName?.lastName ?? ''}`.trim(),
    employee_id:  item.employee?.id ?? '',
    asesor:       item.employee?.label ?? '',
    vin:          item.vehicle?.vin ?? '',
    patente:      item.vehicle?.plate ?? '',
    modelo:       item.vehicle?.modelShortName ?? '',
    modelo_full:  item.vehicle?.modelLongName ?? '',
    km:           item.vehicle?.odometer ?? '',
    revisado:     item.isReviewed ? 'Sí' : 'No',
    recurrente:   item.recurringScheduleStatus === 'Y' ? 'Sí' : 'No',
  }
}));

return allItems;

